import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { MapPin, Phone } from "lucide-react";

import {
  Screen,
  PrimaryButton,
} from "../components/common/UI";

import "../styles/Checkout.css";

export default function Checkout() {
  const navigate = useNavigate();
  const [basket, setBasket] = useState(null);
  const [recipientPhone, setRecipientPhone] = useState("");
  const [payerOption, setPayerOption] = useState("self"); // "self" or "other"
  const [payerPhone, setPayerPhone] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // TODO: Replace with actual API call to GET /baskets/:basketId
    setBasket({
      _id: "1",
      public_id: "BK-1234",
      basket_name: "Weekly groceries",
      merchant: {
        _id: "1",
        business_name: "SupaMart Grocers"
      },
      items: [
        {
          product_id: "1",
          name: "Fresh Milk (500ml)",
          unit_label: "500ml bottle",
          quantity: 2,
          unit_price: { kes: "57.00", aud: "0.63" },
          line_total: { kes: "114.00", aud: "1.26" }
        },
        {
          product_id: "2",
          name: "Sourdough Artisanal Bread",
          unit_label: "1 loaf",
          quantity: 1,
          unit_price: { kes: "400.00", aud: "4.43" },
          line_total: { kes: "400.00", aud: "4.43" }
        }
      ],
      item_count: 3,
      subtotal: { kes: "514.00", aud: "5.69" },
      service_charge: { kes: "50.00", aud: "0.55" },
      total: { kes: "564.00", aud: "6.24" },
      fx_rate: "90.30"
    });
    setLoading(false);
  }, []);

  if (loading) {
    return <Screen title="Checkout" back>Loading...</Screen>;
  }

  if (!basket) {
    return <Screen title="Checkout" back>Basket not found</Screen>;
  }

  const handleCheckout = async () => {
    // TODO: Implement API call to POST /baskets/:basketId/checkout
    // Body: { payer: "self" | "other", recipient_phone?: string, payer_phone?: string }
    const checkoutData = {
      payer: payerOption,
      ...(payerOption === "self" && { recipient_phone: recipientPhone }),
      ...(payerOption === "other" && { payer_phone: payerPhone })
    };

    // After checkout, navigate based on next_action from response
    // If payer: "self" -> navigate to payment flow
    // If payer: "other" -> show "Payment Link Sent" screen
    navigate("/payment/pending");
  };

  return (
    <Screen title="Checkout" back>
      <div className="panel">
        <h3 className="card-title">
          Who should pay?
        </h3>

        <div className="payment-choice-grid">
          <label className={`payment-choice ${payerOption === "self" ? "selected" : ""}`}>
            <input
              type="radio"
              name="payer"
              checked={payerOption === "self"}
              onChange={() => setPayerOption("self")}
            />
            <div>
              <strong>I'll pay myself</strong>
              <small className="muted">Pay with your card</small>
            </div>
          </label>

          <label className={`payment-choice ${payerOption === "other" ? "selected" : ""}`}>
            <input
              type="radio"
              name="payer"
              checked={payerOption === "other"}
              onChange={() => setPayerOption("other")}
            />
            <div>
              <strong>Someone else pays</strong>
              <small className="muted">Share payment link</small>
            </div>
          </label>
        </div>
      </div>

      {payerOption === "self" && (
        <div className="panel">
          <h3 className="card-title">
            Recipient Details
          </h3>

          <label className="field">
            <div className="row">
              <Phone size={14} />
              <span>Recipient's WhatsApp number</span>
            </div>
            <input
              type="tel"
              placeholder="+254 7XX XXX XXX"
              value={recipientPhone}
              onChange={(e) => setRecipientPhone(e.target.value)}
              required
            />
          </label>
        </div>
      )}

      {payerOption === "other" && (
        <div className="panel">
          <h3 className="card-title">
            Payer Details
          </h3>

          <label className="field">
            <div className="row">
              <Phone size={14} />
              <span>Payer's WhatsApp number</span>
            </div>
            <input
              type="tel"
              placeholder="+61 4XX XXX XXX"
              value={payerPhone}
              onChange={(e) => setPayerPhone(e.target.value)}
              required
            />
          </label>
        </div>
      )}

      <div className="panel">
        <h3 className="card-title">
          Order Summary
        </h3>

        <div className="row muted small" style={{ marginBottom: "12px" }}>
          <MapPin size={13} />
          {basket.merchant.business_name}
        </div>

        {basket.items.map((item) => (
          <div
            className="summary-line"
            key={item.product_id}
          >
            <span>
              {item.name} × {item.quantity}
            </span>

            <span>KSh {item.line_total.kes}</span>
          </div>
        ))}

        <div className="summary-line">
          <span>Subtotal ({basket.item_count} items)</span>
          <span>KSh {basket.subtotal.kes}</span>
        </div>

        <div className="summary-line">
          <span>Service charge</span>
          <span>KSh {basket.service_charge.kes}</span>
        </div>

        <div className="divider" />

        <div className="summary-line">
          <strong>Total</strong>
          <strong className="orange">
            KSh {basket.total.kes}
            <span className="aud-price">≈ AUD {basket.total.aud}</span>
          </strong>
        </div>
      </div>

      <PrimaryButton
        disabled={
          (payerOption === "self" && !recipientPhone.trim()) ||
          (payerOption === "other" && !payerPhone.trim())
        }
        onClick={handleCheckout}
      >
        {payerOption === "self" ? "Pay Now" : "Send Payment Link"}
      </PrimaryButton>
    </Screen>
  );
}
